CREATE TABLE IF NOT EXISTS groups (id text PRIMARY KEY, name text NOT NULL, invite_hash text NOT NULL UNIQUE, season integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS members (id text PRIMARY KEY, group_id text NOT NULL REFERENCES groups(id), name text NOT NULL, role text NOT NULL CHECK(role IN ('commissioner','member')), session_hash text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS weeks (id text PRIMARY KEY, group_id text NOT NULL REFERENCES groups(id), number integer NOT NULL, mode text NOT NULL DEFAULT 'top25', size integer NOT NULL DEFAULT 25 CHECK(size BETWEEN 4 AND 25), status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed','published')), deadline timestamptz NOT NULL, UNIQUE(group_id,number,mode));
CREATE TABLE IF NOT EXISTS ballots (week_id text NOT NULL REFERENCES weeks(id), member_id text NOT NULL REFERENCES members(id), teams jsonb NOT NULL, submitted boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(week_id,member_id));
CREATE TABLE IF NOT EXISTS publications (week_id text PRIMARY KEY REFERENCES weeks(id), results jsonb NOT NULL, ballots jsonb NOT NULL, published_at timestamptz NOT NULL DEFAULT now());
